const test=require('node:test'),assert=require('node:assert/strict');
const lib=import('../board-supplies.js');
const base=()=>({id:'village',revision:0,population:0,instances:[{instanceId:'home',cardId:'house',cardRevision:1,capabilities:{housing:6},initialStock:{clay:999}},{instanceId:'shop',cardId:'workshop',cardRevision:1,capabilities:{},initialStock:{clay:999}}],connections:[{a:'home',b:'shop',valid:true}],simulation:null});
test('reserve initialization is explicit and allocations conserve every resource atomically',async()=>{const m=await lib,b=base();assert.throws(()=>m.createSupplies(b.id));b.supplies=m.createSupplies(b.id,m.DEMO_SUPPLY_RESERVE);const before=JSON.stringify(b),next=m.allocateBoardSupplies(b,'shop',{clay:12});assert.equal(JSON.stringify(b),before);assert.equal(next.supplies.reserve.clay,18);assert.equal(m.allocatedStock(next.supplies,b.instances[1]).clay,12);assert.throws(()=>m.allocateBoardSupplies(next,'home',{clay:19}));assert.equal(next.supplies.reserve.clay,18);assert.throws(()=>m.allocateBoardSupplies(next,'shop',{clay:1}));});
test('copy, replacement and missing ledger default empty; deleting does not refund reserve',async()=>{const m=await lib,b=base();b.supplies=m.createSupplies(b.id,{clay:30});const next=m.allocateBoardSupplies(b,'shop',{clay:30});next.instances.push({...next.instances[1],instanceId:'copy'});let adapted=m.withAllocatedSupplies(next,next.supplies);assert.equal(adapted.instances[1].initialStock.clay,30);assert.deepEqual(adapted.instances[2].initialStock,{});next.instances[1].cardRevision=2;assert.deepEqual(m.withAllocatedSupplies(next,next.supplies).instances[1].initialStock,{});next.instances=next.instances.filter(i=>i.instanceId!=='shop');assert.equal(next.supplies.reserve.clay,0);assert.throws(()=>m.allocateBoardSupplies(next,'copy',{clay:1}));assert(m.withAllocatedSupplies(base(),null).instances.every(i=>Object.keys(i.initialStock).length===0));});
test('engine grants only once and consumed or zero-granted instances cannot be reallocated',async()=>{const m=await lib,{createVillageState,advanceVillage}=await import('../village-simulation.js');let b=base();b.supplies=m.createSupplies(b.id,{clay:30});b=m.allocateBoardSupplies(b,'shop',{clay:30});let input=m.withAllocatedSupplies(b,b.supplies),state=createVillageState(input);state=advanceVillage(state,input);assert.equal(state.stock.clay,30);state=advanceVillage(state,input);assert.equal(state.stock.clay,30);b.simulation=state;assert.throws(()=>m.allocateBoardSupplies(b,'home',{clay:1}),/already processed/);b.instances=b.instances.filter(i=>i.instanceId!=='shop');state=advanceVillage(state,{...m.withAllocatedSupplies(b,b.supplies),connections:[]});b.instances.push(base().instances[1]);state=advanceVillage(state,m.withAllocatedSupplies(b,b.supplies));assert.equal(state.stock.clay,30);});
test('whole snapshots round-trip and undo restores reserve and simulation together',async()=>{const m=await lib,b=base();b.supplies=m.createSupplies(b.id,{clay:30});const saved=JSON.stringify(b),next=m.allocateBoardSupplies(b,'shop',{clay:8}),round=JSON.parse(JSON.stringify(next));assert(m.validateSupplies(round.supplies,round.id));assert.equal(round.supplies.reserve.clay,22);const undo=JSON.parse(saved);assert.equal(undo.supplies.reserve.clay,30);assert.equal(undo.supplies.allocations.length,0);assert.equal(undo.simulation,null);});
test('malformed, cross-board, fractional and negative allocations are rejected',async()=>{const m=await lib,b=base(),ledger=m.createSupplies(b.id,{clay:30});for(const amounts of [{clay:-1},{clay:.5},{gold:2},{clay:Infinity},{}])assert.throws(()=>m.allocateSupplies(ledger,b,'shop',amounts));assert.throws(()=>m.allocateSupplies(ledger,{...b,id:'other'},'shop',{clay:1}));assert.throws(()=>m.allocateSupplies(ledger,b,'missing',{clay:1}));const broken=structuredClone(ledger);broken.reserve.clay=31;assert.throws(()=>m.validateSupplies(broken));});
